'use client';
import {useState} from 'react';
type Role='ADMIN'|'ORCAMENTISTA'|'OBRA'|'FINANCEIRO'|'FUNCIONARIO';
const roles:{id:Role;label:string;desc:string}[]=[{id:'ADMIN',label:'Administrador',desc:'Acesso total'},{id:'ORCAMENTISTA',label:'Orçamentista',desc:'Clientes, visitas, materiais e orçamentos'},{id:'OBRA',label:'Responsável de obra',desc:'Obras, horas, materiais, fotos e extras'},{id:'FINANCEIRO',label:'Financeiro',desc:'Caixa, compras, pagamentos e relatórios'},{id:'FUNCIONARIO',label:'Funcionário',desc:'Tarefas e registos autorizados'}];
export default function Funcionarios(){const [rows,setRows]=useState<{name:string;email:string;role:Role}[]>([]);const [name,setName]=useState(''),[email,setEmail]=useState(''),[role,setRole]=useState<Role>('FUNCIONARIO');return <main style={{padding:32,fontFamily:'Arial',maxWidth:1100}}><h1>Funcionários e permissões</h1><p>Utilizadores com login próprio e permissões por função.</p><div style={{display:'grid',gridTemplateColumns:'2fr 2fr 1fr auto',gap:8}}><input placeholder="Nome" value={name} onChange={e=>setName(e.target.value)}/><input placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)}/><select value={role} onChange={e=>setRole(e.target.value as Role)}>{roles.map(r=><option key={r.id}>{r.id}</option>)}</select><button onClick={()=>{if(name&&email){setRows([...rows,{name,email,role}]);setName('');setEmail('')}}}>Adicionar</button></div><div style={{marginTop:25}}>{rows.map((r,i)=><div key={i} style={{padding:16,borderBottom:'1px solid #ddd'}}><strong>{r.name}</strong> · {r.email} · <b>{r.role}</b></div>)}</div><h2 style={{marginTop:35}}>Permissões</h2>{roles.map(r=><div key={r.id} style={{padding:12,borderBottom:'1px solid #ddd'}}><strong>{r.label}</strong> — {r.desc}</div>)}</main>}
